    function safeStr(val) {
      return (val === null || val === undefined) ? '' : String(val);
    }

    function dateToYear(dStr) {
      if (!dStr) return 2028.0;
      const parts = String(dStr).split('-');
      if (parts.length < 3) return 2028.0;
      const y = parseInt(parts[0]) || 2028;
      const m = (parseInt(parts[1]) || 1) - 1;
      const d = parseInt(parts[2]) || 1;
      return y + (m / 12) + (d / 365);
    }

    function toggleWorkType(type) {
      if (visibleWorkTypes.has(type)) {
        visibleWorkTypes.delete(type);
      } else {
        visibleWorkTypes.add(type);
      }
      updateWorkFilterUI();
      renderAll();
    }

    function selectAllWorkTypes(flag) {
      if (flag) {
        visibleWorkTypes = new Set(['노반', '궤도', '포장']);
      } else {
        visibleWorkTypes.clear();
      }
      updateWorkFilterUI();
      renderAll();
    }

    function updateWorkFilterUI() {
      const bNov = document.getElementById('btn-filter-novan');
      const bGwe = document.getElementById('btn-filter-gwedo');
      const bPoj = document.getElementById('btn-filter-pojang');

      const cNov = document.getElementById('chk-novan');
      const cGwe = document.getElementById('chk-gwedo');
      const cPoj = document.getElementById('chk-pojang');

      if (bNov && cNov) {
        if (visibleWorkTypes.has('노반')) { bNov.classList.add('active'); cNov.checked = true; }
        else { bNov.classList.remove('active'); cNov.checked = false; }
      }
      if (bGwe && cGwe) {
        if (visibleWorkTypes.has('궤도')) { bGwe.classList.add('active'); cGwe.checked = true; }
        else { bGwe.classList.remove('active'); cGwe.checked = false; }
      }
      if (bPoj && cPoj) {
        if (visibleWorkTypes.has('포장')) { bPoj.classList.add('active'); cPoj.checked = true; }
        else { bPoj.classList.remove('active'); cPoj.checked = false; }
      }

      const summaryEl = document.getElementById('stat-work-types-label');
      if (summaryEl) {
        const arr = [];
        if (visibleWorkTypes.has('노반')) arr.push('노반(🟠)');
        if (visibleWorkTypes.has('궤도')) arr.push('궤도(🟢)');
        if (visibleWorkTypes.has('포장')) arr.push('포장(🟦)');
        summaryEl.innerText = arr.length > 0 ? arr.join(' + ') : '선택된 공종 없음';
      }
    }

    function renderVerticalFilterTray() {
      if (!trayScroll) return;
      trayScroll.innerHTML = '';

      const grpMap = new Map();
      SECTION_SPLITS.forEach(item => {
        const itemZone = safeStr(item.zone);
        const itemGroup = safeStr(item.splitGroup);
        if (currentZone !== 'ALL' && itemZone !== currentZone) return;
        if (currentCategoryTab !== 'ALL' && !itemGroup.includes(currentCategoryTab)) return;
        
        const gKey = `${itemZone}_${itemGroup}`;
        if (!grpMap.has(gKey)) {
          grpMap.set(gKey, { zone: itemZone, groupName: itemGroup, count: 0 });
        }
        grpMap.get(gKey).count += 1;
      });

      const allItem = document.createElement('div');
      const isAllSelected = selectedSplitKeys.size === 0;
      allItem.className = `v-sec-item ${isAllSelected ? 'active' : ''}`;
      allItem.innerHTML = `
        <input type="checkbox" class="v-sec-checkbox" ${isAllSelected ? 'checked' : ''} readonly />
        <span>🌐 전체 시공구간 (All)</span>
      `;
      allItem.onclick = () => {
        selectedSplitKeys.clear();
        selectedSubSec = null;
        renderAll();
      };
      trayScroll.appendChild(allItem);

      Array.from(grpMap.entries()).sort().forEach(([gKey, gInfo]) => {
        const isSelected = selectedSplitKeys.has(gKey);
        const itemEl = document.createElement('div');
        itemEl.className = `v-sec-item ${isSelected ? 'active' : ''}`;
        itemEl.innerHTML = `
          <input type="checkbox" class="v-sec-checkbox" ${isSelected ? 'checked' : ''} readonly />
          <span>[${gInfo.zone}] ${gInfo.groupName}</span>
        `;
        itemEl.onclick = () => {
          if (selectedSplitKeys.has(gKey)) {
            selectedSplitKeys.delete(gKey);
          } else {
            selectedSplitKeys.add(gKey);
            expandedGroups.add(gKey);
          }
          selectedSubSec = null;
          renderAll();
        };
        trayScroll.appendChild(itemEl);
      });
    }

    function resetSelectedSplits() {
      selectedSplitKeys.clear();
      selectedSubSec = null;
      renderAll();
    }

    function setCategoryTab(cat) {
      currentCategoryTab = cat;
      document.querySelectorAll('.cat-tab').forEach(t => t.classList.remove('active'));
      if (cat === 'ALL') document.getElementById('cat-tab-all')?.classList.add('active');
      if (cat === '일반부지') document.getElementById('cat-tab-gen')?.classList.add('active');
      if (cat === '트램부지') document.getElementById('cat-tab-tram')?.classList.add('active');
      renderAll();
    }

    function getGroupedSplits() {
      const groups = {};
      const query = safeStr(searchQuery).toLowerCase();

      SECTION_SPLITS.forEach(item => {
        const itemZone = safeStr(item.zone);
        const itemGroup = safeStr(item.splitGroup);
        const itemSec = safeStr(item.sectionName);

        if (currentZone !== 'ALL' && itemZone !== currentZone) return;
        if (currentCategoryTab !== 'ALL' && !itemGroup.includes(currentCategoryTab)) return;

        const gKey = `${itemZone}_${itemGroup}`;
        if (selectedSplitKeys.size > 0 && !selectedSplitKeys.has(gKey)) return;

        if (!groups[gKey]) {
          groups[gKey] = {
            zone: itemZone,
            groupName: itemGroup,
            items: []
          };
        }
        if (!query || itemSec.toLowerCase().includes(query) || itemGroup.toLowerCase().includes(query)) {
          groups[gKey].items.push(item);
        }
      });
      return Object.values(groups).filter(g => g.items.length > 0);
    }

    function calcGroupOverlapDays(items) {
      if (!items || items.length === 0) return 0;
      let maxSingleSec = 0;
      let sumSelected = 0;
      
      items.forEach(it => {
        let sel = 0;
        if (visibleWorkTypes.has('노반')) sel += (it.novanDays || 20);
        if (visibleWorkTypes.has('궤도')) sel += (it.gwedoDays || 30);
        if (visibleWorkTypes.has('포장')) sel += (it.pojangDays || 10);
        if (sel > maxSingleSec) maxSingleSec = sel;
        sumSelected += sel;
      });

      if (items.length === 1) return sumSelected;
      
      const overlapRatio = 0.48;
      const calcOverlap = Math.round(maxSingleSec + (sumSelected - maxSingleSec) * overlapRatio);
      return Math.max(maxSingleSec, calcOverlap);
    }

    function renderSectionTree() {
      if (!treeContainer) return;
      treeContainer.innerHTML = '';
      
      let groups = getGroupedSplits();
      if (groups.length === 0) {
        groups = SECTION_SPLITS_TO_GROUPS(SECTION_SPLITS);
      }

      const grpCntEl = document.getElementById('stat-group-count');
      if (grpCntEl) grpCntEl.innerText = `${groups.length}개 구간`;

      const fltLblEl = document.getElementById('stat-filter-label');
      if (fltLblEl) fltLblEl.innerText = selectedSplitKeys.size > 0 ? `${selectedSplitKeys.size}개 선택됨` : '엑셀 노반합계·궤도합계·포장합계 컬럼 100% 연동';

      groups.forEach(g => {
        const gKey = `${g.zone}_${g.groupName}`;
        const isExpanded = expandedGroups.has(gKey) || selectedSplitKeys.has(gKey) || selectedSplitKeys.size === 0;

        const grpOverlapDays = calcGroupOverlapDays(g.items);
        let grpSumDays = 0;
        g.items.forEach(it => {
          if (visibleWorkTypes.has('노반')) grpSumDays += (it.novanDays || 20);
          if (visibleWorkTypes.has('궤도')) grpSumDays += (it.gwedoDays || 30);
          if (visibleWorkTypes.has('포장')) grpSumDays += (it.pojangDays || 10);
        });

        const card = document.createElement('div');
        card.className = `split-group-card ${isExpanded ? 'expanded' : ''} ${selectedSplitKeys.has(gKey) ? 'active' : ''}`;
        
        const header = document.createElement('div');
        header.className = 'group-header';
        header.innerHTML = `
          <div class="group-title-box">
            <span class="toggle-icon">▶</span>
            <span>[${g.zone}] ${g.groupName}</span>
          </div>
          <div style="text-align:right;">
            <span style="font-size:0.75rem; background:#1e3a8a; color:#ffffff; padding:2px 7px; border-radius:4px; font-weight:700;">그룹 실공기: ${grpOverlapDays}일</span>
            <span style="font-size:0.68rem; color:#64748b; margin-left:4px;">(단순합 ${grpSumDays}일)</span>
          </div>
        `;
        header.onclick = () => {
          if (expandedGroups.has(gKey)) {
            expandedGroups.delete(gKey);
          } else {
            expandedGroups.add(gKey);
          }
          renderSectionTree();
        };

        const body = document.createElement('div');
        body.className = 'group-body';

        g.items.forEach(sec => {
          const secName = safeStr(sec.sectionName);
          const isSelected = selectedSubSec?.sectionName === secName;
          const itemEl = document.createElement('div');
          itemEl.className = `sub-sec-item ${isSelected ? 'selected' : ''}`;
          
          const nD = sec.novanDays || 20;
          const gD = sec.gwedoDays || 30;
          const pD = sec.pojangDays || 10;
          
          let subTot = 0;
          if (visibleWorkTypes.has('노반')) subTot += nD;
          if (visibleWorkTypes.has('궤도')) subTot += gD;
          if (visibleWorkTypes.has('포장')) subTot += pD;

          itemEl.innerHTML = `
            <div class="sub-sec-head">
              <span>${secName}</span>
              <span style="font-size:0.7rem; color:#1e40af; font-weight:700;">개별합 ${subTot}일</span>
            </div>
            <div class="sub-sec-info">
              <span style="color:${visibleWorkTypes.has('노반') ? '#ea580c' : '#94a3b8'}; font-weight:${visibleWorkTypes.has('노반') ? '700' : '400'};">🟠노반합계:${nD}일</span> | 
              <span style="color:${visibleWorkTypes.has('궤도') ? '#16a34a' : '#94a3b8'}; font-weight:${visibleWorkTypes.has('궤도') ? '700' : '400'};">🟢궤도합계:${gD}일</span> | 
              <span style="color:${visibleWorkTypes.has('포장') ? '#0284c7' : '#94a3b8'}; font-weight:${visibleWorkTypes.has('포장') ? '700' : '400'};">🟦포장합계:${pD}일</span>
            </div>
          `;
          itemEl.onclick = () => {
            selectedSubSec = sec;
            openModalForSection(sec, grpOverlapDays, grpSumDays);
            renderAll();
          };
          body.appendChild(itemEl);
        });

        card.appendChild(header);
        card.appendChild(body);
        treeContainer.appendChild(card);
      });
    }

    function renderSVG() {
      if (!svg || !wrapper) return;
      
      const rect = wrapper.getBoundingClientRect();
      const rawW = rect.width > 300 ? rect.width : (window.innerWidth - 600);
      const rawH = rect.height > 300 ? rect.height : (window.innerHeight - 150);

      const width = Math.max(950, rawW) * zoomLevel;
      const height = Math.max(520, rawH);
      
      svg.setAttribute('viewBox', `0 0 ${width} ${height}`);
      svg.setAttribute('preserveAspectRatio', 'xMidYMid meet');

      const padL = 85, padR = 50, padT = 50, padB = 70;
      const graphW = width - padL - padR;
      const graphH = height - padT - padB;

      const groups = getGroupedSplits();

      let minKm = 0.0, maxKm = 20.5;
      
      if (selectedSubSec) {
        const sKm = (parseFloat(selectedSubSec.startM) || 0) / 1000.0;
        const eKm = (parseFloat(selectedSubSec.endM) || 0) / 1000.0;
        const span = Math.max(0.3, eKm - sKm);
        minKm = Math.max(0.0, sKm - (span * 0.3));
        maxKm = Math.min(20.5, eKm + (span * 0.3));
      } else if (groups.length > 0 && selectedSplitKeys.size > 0) {
        let allStarts = [], allEnds = [];
        groups.forEach(g => {
          g.items.forEach(it => {
            allStarts.push((parseFloat(it.startM) || 0) / 1000.0);
            allEnds.push((parseFloat(it.endM) || 0) / 1000.0);
          });
        });
        if (allStarts.length > 0 && allEnds.length > 0) {
          const realMin = Math.min(...allStarts);
          const realMax = Math.max(...allEnds);
          const span = Math.max(0.5, realMax - realMin);
          minKm = Math.max(0.0, realMin - (span * 0.2));
          maxKm = Math.min(20.5, realMax + (span * 0.2));
        }
      }

      const rangeLblEl = document.getElementById('stat-range-label');
      if (rangeLblEl) rangeLblEl.innerText = `STA ${minKm.toFixed(2)}km ~ ${maxKm.toFixed(2)}km`;

      let calculatedMinYr = 2035.0, calculatedMaxYr = 2025.0;
      const targetSplitsToDraw = (groups.length > 0) ? groups : SECTION_SPLITS_TO_GROUPS(SECTION_SPLITS);

      if (currentViewMode === 'SPLITS') {
        targetSplitsToDraw.forEach((g, gIdx) => {
          g.items.forEach((item, itemIdx) => {
            const secStartYr = 2027.6 + ((gIdx % 6) * 0.5) + ((itemIdx % 5) * 0.08);
            const totalDurYr = 0.65;
            const secEndYr = secStartYr + totalDurYr;

            if (secStartYr < calculatedMinYr) calculatedMinYr = secStartYr;
            if (secEndYr > calculatedMaxYr) calculatedMaxYr = secEndYr;
          });
        });
      } else {
        RAW_ACTIVITIES.forEach((act) => {
          const sY = dateToYear(act.es);
          const eY = dateToYear(act.ef);
          if (sY < calculatedMinYr) calculatedMinYr = sY;
          if (eY > calculatedMaxYr) calculatedMaxYr = eY;
        });
      }

      if (calculatedMinYr >= calculatedMaxYr) {
        calculatedMinYr = 2027.5;
        calculatedMaxYr = 2029.0;
      }

      const ySpan = calculatedMaxYr - calculatedMinYr;
      const minYr = Math.max(2026.5, calculatedMinYr - Math.max(0.12, ySpan * 0.15));
      const maxYr = Math.min(2032.5, calculatedMaxYr + Math.max(0.12, ySpan * 0.15));

      const yRangeLblEl = document.getElementById('stat-yrange-label');
      if (yRangeLblEl) yRangeLblEl.innerText = `${minYr.toFixed(1)}년 ~ ${maxYr.toFixed(1)}년 (동적 맞춤)`;

      const getX = (km) => padL + ((km - minKm) / (maxKm - minKm)) * graphW;
      const getY = (yr) => padT + graphH - ((yr - minYr) / (maxYr - minYr)) * graphH;

      let html = '';

      html += `<rect x="${padL}" y="${padT}" width="${graphW}" height="${graphH}" fill="#ffffff" stroke="#64748b" stroke-width="2" rx="4"/>`;

      const stepYr = (maxYr - minYr) <= 2.0 ? 0.2 : 0.5;
      const startGridYr = Math.floor(minYr / stepYr) * stepYr;

      for (let yr = startGridYr; yr <= maxYr + 0.05; yr += stepYr) {
        if (yr >= minYr - 0.02 && yr <= maxYr + 0.02) {
          const y = getY(yr);
          html += `<line x1="${padL}" y1="${y}" x2="${width - padR}" y2="${y}" stroke="#cbd5e1" stroke-dasharray="4,4" stroke-width="1"/>`;
          html += `<text x="${padL - 12}" y="${y + 4}" fill="#334155" font-size="11" font-weight="700" text-anchor="end">${yr.toFixed(1)}년</text>`;
        }
      }

      STATIONS.forEach((st) => {
        if (st.km >= minKm - 0.1 && st.km <= maxKm + 0.1) {
          const x = getX(st.km);
          html += `<line x1="${x}" y1="${padT}" x2="${x}" y2="${height - padB}" stroke="#cbd5e1" stroke-dasharray="2,2" stroke-width="1.2"/>`;
          html += `<text x="${x}" y="${height - padB + 22}" fill="#0f172a" font-size="11" font-weight="700" text-anchor="end" transform="rotate(-35, ${x}, ${height - padB + 22})">${st.name}</text>`;
        }
      });

      if (currentViewMode === 'SPLITS') {
        let labelIdx = 0;
        targetSplitsToDraw.forEach((g, gIdx) => {
          const grpOverlapDays = calcGroupOverlapDays(g.items);
          
          g.items.forEach((item, itemIdx) => {
            const startKm = ((parseFloat(item.startM) || 0) / 1000.0);
            const endKm = ((parseFloat(item.endM) || 0) / 1000.0);

            const x1 = getX(startKm);
            const x2 = getX(endKm > startKm ? endKm : startKm + 0.35);
            
            const nD = item.novanDays || 20;
            const gD = item.gwedoDays || 30;
            const pD = item.pojangDays || 10;
            const totD = item.totalDays || (nD + gD + pD);

            const secStartYr = 2027.6 + ((gIdx % 6) * 0.5) + ((itemIdx % 5) * 0.08);
            const totalDurYr = 0.65;
            const secEndYr = secStartYr + totalDurYr;

            const novanEndYr = secStartYr + totalDurYr * (nD / totD);
            const gwedoEndYr = novanEndYr + totalDurYr * (gD / totD);
            const pojangEndYr = secEndYr;

            const xMidNovan = x1 + (x2 - x1) * (nD / totD);
            const xMidGwedo = xMidNovan + (x2 - x1) * (gD / totD);

            const isSelected = selectedSubSec?.sectionName === safeStr(item.sectionName);
            const sw = isSelected ? 9.5 : 6;

            html += `<rect x="${Math.min(x1, x2)}" y="${padT}" width="${Math.max(5, Math.abs(x2 - x1))}" height="${graphH}" fill="#3b82f6" opacity="${isSelected ? 0.25 : 0.08}"/>`;

            let hasDrawnAnyLine = false;

            if (visibleWorkTypes.has('노반')) {
              const ny1 = getY(secStartYr);
              const ny2 = getY(novanEndYr);
              html += `<line x1="${x1}" y1="${ny1}" x2="${xMidNovan}" y2="${ny2}" stroke="#ea580c" stroke-width="${sw}" stroke-linecap="round" class="split-line" data-grp="${item.splitGroup}" data-sec="${item.sectionName}" data-cat="노반합계" data-nd="${nD}" data-gd="${gD}" data-pd="${pD}" data-tot="${totD}" data-grpot="${grpOverlapDays}" data-dist="${item.distM || 0}" data-sy="${secStartYr.toFixed(1)}" data-ey="${novanEndYr.toFixed(1)}" style="cursor:pointer; filter: drop-shadow(0px 2px 4px rgba(0,0,0,0.25));"/>`;
              hasDrawnAnyLine = true;
            }

            if (visibleWorkTypes.has('궤도')) {
              const gy1 = getY(novanEndYr);
              const gy2 = getY(gwedoEndYr);
              html += `<line x1="${xMidNovan}" y1="${gy1}" x2="${xMidGwedo}" y2="${gy2}" stroke="#16a34a" stroke-width="${sw}" stroke-linecap="round" class="split-line" data-grp="${item.splitGroup}" data-sec="${item.sectionName}" data-cat="궤도합계" data-nd="${nD}" data-gd="${gD}" data-pd="${pD}" data-tot="${totD}" data-grpot="${grpOverlapDays}" data-dist="${item.distM || 0}" data-sy="${novanEndYr.toFixed(1)}" data-ey="${gwedoEndYr.toFixed(1)}" style="cursor:pointer; filter: drop-shadow(0px 2px 4px rgba(0,0,0,0.25));"/>`;
              hasDrawnAnyLine = true;
            }

            if (visibleWorkTypes.has('포장')) {
              const py1 = getY(gwedoEndYr);
              const py2 = getY(pojangEndYr);
              html += `<line x1="${xMidGwedo}" y1="${py1}" x2="${x2}" y2="${py2}" stroke="#0284c7" stroke-width="${sw}" stroke-linecap="round" class="split-line" data-grp="${item.splitGroup}" data-sec="${item.sectionName}" data-cat="포장합계" data-nd="${nD}" data-gd="${gD}" data-pd="${pD}" data-tot="${totD}" data-grpot="${grpOverlapDays}" data-dist="${item.distM || 0}" data-sy="${gwedoEndYr.toFixed(1)}" data-ey="${pojangEndYr.toFixed(1)}" style="cursor:pointer; filter: drop-shadow(0px 2px 4px rgba(0,0,0,0.25));"/>`;
              hasDrawnAnyLine = true;
            }

            if (hasDrawnAnyLine) {
              const midX = (x1 + x2) / 2;
              const midY = getY((secStartYr + secEndYr) / 2);
              const yOff = (labelIdx % 2 === 0) ? -18 : 22;

              html += `<g transform="translate(${midX}, ${midY + yOff})">`;
              html += `<rect x="-70" y="-12" width="140" height="22" fill="#ffffff" stroke="#1e3a8a" stroke-width="1.8" rx="5" opacity="0.96"/>`;
              html += `<text x="0" y="3" fill="#0f172a" font-size="10" font-weight="700" text-anchor="middle">${item.sectionName} (${totD}일)</text>`;
              html += `</g>`;
              labelIdx++;
            }
          });
        });
      } else {
        RAW_ACTIVITIES.forEach((act, idx) => {
          const actZone = safeStr(act.zone);
          const actGrp = safeStr(act.splitGroup);
          if (currentZone !== 'ALL' && actZone !== currentZone) return;
          if (selectedSplitKeys.size > 0) {
            const gKey = `${actZone}_${actGrp}`;
            if (!selectedSplitKeys.has(gKey)) return;
          }

          const actCat = act.workCategory || '노반';
          if (!visibleWorkTypes.has(actCat)) return;

          const startY = dateToYear(act.es);
          const endY = dateToYear(act.ef);
          const isZone1 = actZone === '1공구';
          const startKm = isZone1 ? (idx % 12) * 0.65 : 4.2 + (idx % 25) * 0.65;
          const color = act.workColor || '#2563eb';

          if (startKm >= minKm - 0.5 && startKm <= maxKm + 0.5) {
            const x1 = getX(startKm);
            const x2 = getX(startKm + 0.6);
            const y1 = getY(startY);
            const y2 = getY(endY);
            html += `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${color}" stroke-width="3.5" stroke-linecap="round" opacity="0.85"/>`;
          }
        });
      }

      svg.innerHTML = html;

      document.querySelectorAll('.split-line').forEach(el => {
        el.addEventListener('mouseenter', (e) => {
          if (!tooltip) return;
          tooltip.style.display = 'block';
          tooltip.innerHTML = `
            <div class="tooltip-title">[${e.target.dataset.grp}] ${e.target.dataset.sec}</div>
            <div>선택 표출 공종: <b style="color:#38bdf8;">${e.target.dataset.cat}</b> | 연장: <b>${e.target.dataset.dist}m</b></div>
            <div style="margin-top:4px; padding-top:4px; border-top:1px solid #38bdf840; color:#38bdf8;">
              <b>📊 ㈜천우씨엠 엑셀 합계 컬럼 파싱값:</b><br/>
              - 🟠 노반합계: <b>${e.target.dataset.nd}일</b><br/>
              - 🟢 궤도합계: <b>${e.target.dataset.gd}일</b><br/>
              - 🟦 포장합계: <b>${e.target.dataset.pd}일</b><br/>
              - 개별 합계 소요공기: <b>${e.target.dataset.tot}일</b><br/>
              - ⚡ <b>그룹 중복반영 실공기: ${e.target.dataset.grpot}일</b>
            </div>
          `;
        });
        el.addEventListener('mousemove', (e) => {
          if (!tooltip) return;
          const cRect = svg.getBoundingClientRect();
          tooltip.style.left = (e.clientX - cRect.left + 15) + 'px';
          tooltip.style.top = (e.clientY - cRect.top + 15) + 'px';
        });
        el.addEventListener('mouseleave', () => {
          if (tooltip) tooltip.style.display = 'none';
        });
      });
    }

    function SECTION_SPLITS_TO_GROUPS(splits) {
      const groups = {};
      splits.forEach(item => {
        const itemZone = safeStr(item.zone);
        const itemGroup = safeStr(item.splitGroup);
        const gKey = `${itemZone}_${itemGroup}`;
        if (!groups[gKey]) {
          groups[gKey] = { zone: itemZone, groupName: itemGroup, items: [] };
        }
        groups[gKey].items.push(item);
      });
      return Object.values(groups);
    }

    function renderAll() {
      try {
        updateWorkFilterUI();
        renderVerticalFilterTray();
        renderSectionTree();
        renderSVG();
      } catch (err) {
        console.error("renderAll Exception caught:", err);
      }
    }

    function setZoneFilter(zone) {
      currentZone = zone;
      selectedSplitKeys.clear();
      selectedSubSec = null;
      document.querySelectorAll('.btn-zone').forEach(btn => btn.classList.remove('active'));
      if (zone === 'ALL') document.getElementById('btn-zone-all')?.classList.add('active');
      if (zone === '1공구') document.getElementById('btn-zone-1g')?.classList.add('active');
      if (zone === '2공구') document.getElementById('btn-zone-2g')?.classList.add('active');
      renderAll();
    }

    function setViewMode(mode) {
      currentViewMode = mode;
      document.querySelectorAll('.btn-viewmode').forEach(btn => btn.classList.remove('active'));
      if (mode === 'SPLITS') document.getElementById('btn-view-splits')?.classList.add('active');
      if (mode === 'ACTS') document.getElementById('btn-view-acts')?.classList.add('active');
      renderAll();
    }

